func (r *mailPublicFolderResource) Delete(_ context.Context, _ resource.DeleteRequest, resp *resource.DeleteResponse) {
	resp.Diagnostics.AddWarning("MailPublicFolder configuration not deleted", "This resource manages an existing MailPublicFolder configuration. It has been removed from Terraform state, but the configuration itself remains unchanged in the tenant.")
}

func (r *mailPublicFolderResource) ImportState(ctx context.Context, req resource.ImportStateRequest, resp *resource.ImportStateResponse) {
	resp.Diagnostics.Append(resp.State.SetAttribute(ctx, path.Root("id"), req.ID)...)
	resp.Diagnostics.Append(resp.State.SetAttribute(ctx, path.Root("identity"), req.ID)...)
}

func (r *mailPublicFolderResource) identityOf(m mailPublicFolderModel) string {
	if v := m.Identity.ValueString(); v != "" {
		return v
	}
	if v := m.ID.ValueString(); v != "" {
		return v
	}
	return m.Name.ValueString()
}

func (r *mailPublicFolderResource) refresh(ctx context.Context, identity string, m *mailPublicFolderModel, diags *diag.Diagnostics, reflected func(map[string]any) bool) bool {
	get := func(ctx context.Context) (map[string]any, bool, error) {
		res, gerr := r.client.EXO.GetMailPublicFolder(ctx, exo.GetMailPublicFolderParams{Identity: identity})
		if gerr != nil {
			if isNotFound(gerr) {
				return nil, false, nil
			}
			return nil, false, gerr
		}
		o := firstObject(res.Value)
		return o, o != nil, nil
	}
	obj, present, err := resourcex.LoadUntil(ctx, consistency.Config{}, get, reflected)
	if err != nil {
		diags.AddError("Get-MailPublicFolder failed", err.Error())
		return false
	}
	if !present {
		return false
	}
	readMailPublicFolder(ctx, obj, m)
	return true
}

